CREATE TABLE [dbo].[ccAgendaListaNegra](	  [campsid] INT NOT NULL	, [fecharegs] DATETIME NOT NULL	, [fechaaplicar] DATETIME NOT NULL	, [fechacaptura] DATETIME NOT NULL DEFAULT(getdate())	, [inicio] DATETIME NULL	, [termino] DATETIME NULL	, [status] TINYINT NOT NULL DEFAULT(1)	, [idagenda] INT NOT NULL IDENTITY(1,1))CREATE NONCLUSTERED INDEX [IX_ccAgendaListaNegra] ON [dbo].[ccAgendaListaNegra] ([idagenda] ASC)CREATE NONCLUSTERED INDEX [IX_ccAgendaListaNegra_1] ON [dbo].[ccAgendaListaNegra] ([status] ASC)CREATE NONCLUSTERED INDEX [IX_ccAgendaListaNegra_2] ON [dbo].[ccAgendaListaNegra] ([campsid] ASC)CREATE NONCLUSTERED INDEX [IX_ccAgendaListaNegra_3] ON [dbo].[ccAgendaListaNegra] ([fechaaplicar] ASC)CREATE NONCLUSTERED INDEX [IX_ccAgendaListaNegra_4] ON [dbo].[ccAgendaListaNegra] ([status] ASC, [fechaaplicar] ASC)INCLUDE ([idagenda], [campsid], [fecharegs])